type SlashCommandItem = { id: string; label: string; keywords?: string };
type SlashCommandMenuProps = {
    items: readonly SlashCommandItem[];
    activeIndex: number;
    onSelect: (item: SlashCommandItem) => void;
};

function SlashCommandMenu({
    items, activeIndex, onSelect,
}: SlashCommandMenuProps) {
    return <div role="listbox" aria-label="블록 명령"
        data-slot="slash-command-menu"
        className="grid rounded-md border border-border bg-surface p-1">
        {items.length === 0 && <p role="status">검색 결과가 없습니다.</p>}
        {items.map((item, index) => <button type="button" role="option"
            key={item.id} aria-selected={index === activeIndex}
            onMouseDown={(event) => event.preventDefault()}
            onClick={() => onSelect(item)}
            className="rounded-sm p-2 text-left aria-selected:bg-surface-subtle">
            {item.label}
        </button>)}
    </div>;
}

export { SlashCommandMenu };
export type { SlashCommandItem, SlashCommandMenuProps };
